    List<ILocalResearch> inProgress = colony.getResearchManager().getResearchTree().getResearchInProgress();
    WorkerBuildingModule module = (WorkerBuildingModule)this.getModuleMatching(WorkerBuildingModule.class, m -> m.getJobEntry() == ModJobs.researcher.get());
