    MessageUtils.format((Component)message).sendTo(this.colony).forManagers();
    this.colony.getResearchManager().checkAutoStartResearch();
    this.markDirty();
}

@Override
public void processOfflineTime(long time) {
    if (this.getBuildingLevel() >= 3 && time > 0L) {
