public class BeekeeperCollectionSetting
extends StringSetting {
    private boolean hasResearch;

    public BeekeeperCollectionSetting(String ... settings) {
        super(settings);
    }

    public BeekeeperCollectionSetting(List<String> settings, int currentIndex) {
        super(settings, currentIndex);
    }

    @Override
    @OnlyIn(value=Dist.CLIENT)
    public void setupHandler(ISettingKey<?> key, Pane pane, ICommonSettingsModule settingsModuleView, IBuildingView building, BOWindow window) {
        this.hasResearch = building.getColony().getResearchManager().getResearchEffects().getEffectStrength(ResearchConstants.BEEKEEP_2) > 0.0;
        ((ButtonImage)pane.findPaneOfTypeByID("trigger", ButtonImage.class)).setHandler(button -> settingsModuleView.trigger(key));
    }

    @Override
    public boolean isIndexAllowed(int index) {
        return super.isIndexAllowed(index) && (this.hasResearch || !this.getSettings().get(index).equals("com.minecolonies.core.apiary.setting.both"));
    }
}

